use xiom.io;
interface Displayable {
  fn display() -> Str;
}

type Book = {
  title: Str;
  author: Str;
}

fn Book.display(self) -> Str {
  return "'" + self.title + "' by " + self.author;
}

fn print_item[T: Displayable](item: &T) {
  io.println(item.display());
}

fn main() -> Int {
  let book = Book{ title: "XIOM Guide", author: "Kai" };
  print_item(&book);
  return 0;
}
